/**
 * Music and sound effects with the Echo sound driver, on a Mega Drive
 * cartridge.
 *
 * echo_init uploads Echo to the Z80 with the instrument list; after that the
 * 68000 only sends commands (play, stop, pause, a sound effect) and the Z80
 * plays everything. The song, the effects and the instrument list are in
 * song.s, generated by tools/gen_song.py.
 *
 * Controller reads happen with the Z80 bus held: see read_pad.
 */
#include "shortcuts.h"
#include <cpu.h>
#include <main/echo.h>
#include <main/io.h>
#include <main/memmap.h>
#include <main/text.h>
#include <main/vdp.h>
#include <main/z80.h>
#include <stdio.h>

// song.s
extern void const * const instrument_list[];
extern u8 const           song[], sfx_beep[], sfx_chime[];

#define PLANE_A_ADDR    0x2000
#define PLANE_B_ADDR    0x4000
#define SPRITE_TBL_ADDR 0xb800

// The system font is loaded at tile 0x20, so a character's tile is its code.
// Palette line 1 colors the headings.
#define TEXT_TILE      0x20
#define HEADING_TILE   (0x20 | (1 << 13))
#define plane_xy(x, y) VDP_PLANE_XY(PLANE_A_ADDR, x, y, Width64)

static void print_at(char const * s, u8 x, u8 y)
{
  text_print(s, plane_xy(x, y), TEXT_TILE);
}

static void heading_at(char const * s, u8 x, u8 y)
{
  text_print(s, plane_xy(x, y), HEADING_TILE);
}

__attribute__((interrupt)) void INT2_EXT()
{
  return;
}

__attribute__((interrupt)) void INT4_HBLANK()
{
  return;
}

volatile bool vblank_done;

__attribute__((interrupt)) void INT6_VBLANK()
{
  vblank_done = true;
}

static void wait_vblank()
{
  vblank_done = false;
  while (! vblank_done)
    ;
}

#if VIDEO == PAL
#define VIDEO_SIGNAL VDP_PAL_VIDEO
#else
#define VIDEO_SIGNAL 0
#endif

static u16 const vdp_init_regs[] = {
  VDP_REG_MODE1 | VDP_HICOLOR_ENABLE,
  VDP_REG_MODE2 | VDP_MD_DISPLAY_MODE | VDP_VBLANK_ENABLE | VIDEO_SIGNAL |
    VDP_DISPLAY_ENABLE,
  VDP_REG_PLA_ADDR | (PLANE_A_ADDR / 0x400),
  VDP_REG_WIN_ADDR | (0xa00 / 0x400),
  VDP_REG_PLB_ADDR | (PLANE_B_ADDR / 0x2000),
  VDP_REG_SPR_ADDR | (SPRITE_TBL_ADDR / 0x200),
  VDP_REG_SPR_ADDR2,
  VDP_REG_BGCOLOR,
  VDP_REG_HBLANK_COUNT,
  VDP_REG_MODE3,
  VDP_REG_MODE4 | VDP_WIDTH_40CELL_MASK,
  VDP_REG_HS_ADDR | (0xbc00 / 0x400),
  VDP_REG_PL_ADDR2,
  VDP_REG_AUTOINC | 2,
  VDP_REG_PL_SIZE | VDP_PL_64x32,
  VDP_REG_WIN_HPOS,
  VDP_REG_WIN_VPOS};

static void init_video()
{
  for (u8 i = 0; i < sizeof vdp_init_regs / sizeof vdp_init_regs[0]; ++i)
    vdp_ctrl = vdp_init_regs[i];

  vdp_ctrl_32 = to_vdp_addr(0) | VRAM_W;
  for (u16 i = 0; i < (0x10000 / 4); ++i)
    vdp_data_32 = 0;

  // line 0: black background, white text; line 1: yellow headings
  vdp_ctrl_32 = to_vdp_addr(0) | CRAM_W;
  vdp_data = 0x0000;
  vdp_data = 0x0EEE;
  vdp_ctrl_32 = to_vdp_addr(0x20) | CRAM_W;
  vdp_data = 0x0000;
  vdp_data = 0x00EE;

  vdp_load_1bpp_tiles(sysfont, SYSFONT_CHARS, TEXT_TILE, 1, 0);
}

/**
 * Read controller 1, buttons pressed set to 1.
 *
 * While Echo runs, an access to the I/O ports can corrupt a byte the Z80 is
 * fetching from ROM at that moment, so the read is done with the Z80 bus held.
 * Interrupts are masked so that no handler can release the bus in between.
 * Keep the section short: Echo stops while it is held.
 */
static u8 read_pad()
{
  u16 const sr = mask_interrupts();
  z80_request_bus();
  u8 const pad = ~read_input_joypad(io_data1);
  z80_release_bus();
  restore_interrupts(sr);
  return pad;
}

enum { STOPPED, PLAYING, PAUSED };

static char const * const music_state_names[] = {
  "STOPPED", "PLAYING", "PAUSED "};

// Global volume in 16 steps; echo_set_volume takes 0 to 255. It scales FM
// and PSG; PCM has no volume and is muted below 64 (step 4).
#define VOLUME_STEPS 16

static u8 volume_to_echo(u8 step)
{
  return step == VOLUME_STEPS ? 255 : step * 16;
}

void main()
{
  char buf[40];
  u8   music = PLAYING;
  u8   volume = VOLUME_STEPS;
  u8   prev_pad = 0;

  init_video();
  init_joypads();
  enable_interrupts();

  heading_at("ECHO SOUND DRIVER", 2, 2);
  print_at("START   PLAY / STOP MUSIC", 2, 5);
  print_at("A       PAUSE / RESUME MUSIC", 2, 6);
  print_at("B       EFFECT ON PSG3 (FREE)", 2, 7);
  print_at("C       EFFECT ON FM5 (BORROWED)", 2, 8);
  print_at("UP/DOWN VOLUME", 2, 9);
  heading_at("MUSIC", 2, 12);
  heading_at("VOLUME", 2, 13);
  heading_at("STATUS", 2, 14);

  echo_init(instrument_list);
  echo_play_bgm(song);

  for (;;) {
    wait_vblank();

    u8 const pad = read_pad();
    u8 const pressed = pad & ~prev_pad;
    prev_pad = pad;

    if (pressed & PAD_START) {
      if (music == STOPPED) {
        echo_play_bgm(song);
        music = PLAYING;
      } else {
        echo_stop_bgm();
        music = STOPPED;
      }
    }
    if (pressed & PAD_A) {
      if (music == PLAYING) {
        echo_pause_bgm();
        music = PAUSED;
      } else if (music == PAUSED) {
        echo_resume_bgm();
        music = PLAYING;
      }
    }
    if (pressed & PAD_B)
      echo_play_sfx(sfx_beep);
    if (pressed & PAD_C)
      echo_play_sfx(sfx_chime);
    if ((pressed & PAD_UP) && volume < VOLUME_STEPS)
      echo_set_volume(volume_to_echo(++volume));
    if ((pressed & PAD_DOWN) && volume > 0)
      echo_set_volume(volume_to_echo(--volume));

    // echo_get_status: ECHO_STAT_BGM while music plays, ECHO_STAT_SFX while
    // an effect plays
    u16 const status = echo_get_status();
    print_at(music_state_names[music], 10, 12);
    snprintf(buf, sizeof buf, "%2u/%u", volume, VOLUME_STEPS);
    print_at(buf, 10, 13);
    snprintf(
      buf,
      sizeof buf,
      "%04X %s %s",
      status,
      (status & ECHO_STAT_BGM) ? "BGM" : "   ",
      (status & ECHO_STAT_SFX) ? "SFX" : "   ");
    print_at(buf, 10, 14);
  }
}
